const RTT_MS = 40;
const tcp = RTT_MS;            // TCP SYN/SYN-ACK = 1 RTT
const tls13 = RTT_MS;          // TLS 1.3 = 1 RTT
const tls12 = 2 * RTT_MS;      // TLS 1.2 = 2 RTT
const t13 = tcp + tls13;
const t12 = tcp + tls12;
console.log('RTT=' + RTT_MS + 'ms');
console.log('TCP+TLS1.3 = ' + t13 + 'ms (' + (t13 / RTT_MS) + ' RTT)');
console.log('TCP+TLS1.2 = ' + t12 + 'ms (' + (t12 / RTT_MS) + ' RTT)');
console.log('saved = ' + (t12 - t13) + 'ms (' + ((t12 - t13) / RTT_MS) + ' RTT)');
